const responseBody = pm.response.text();

// 1. Status code
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Response is not empty
pm.test("Response body is not empty", function () {
    pm.expect(responseBody).to.not.be.empty;
});

// 3. Response contains SOAP Envelope
pm.test("Response contains SOAP Envelope", function () {
    pm.expect(responseBody).to.include("Envelope");
});

// 4. Response contains SOAP Body
pm.test("Response contains SOAP Body", function () {
    pm.expect(responseBody).to.include("Body");
});

// 5. Response contains ISBN13 response
pm.test("Response contains IsValidISBN13Response", function () {
    pm.expect(responseBody).to.include("IsValidISBN13Response");
});

// 6. ISBN13 result exists
pm.test("ISBN13 result exists", function () {
    pm.expect(responseBody).to.include("IsValidISBN13Result");
});

// 7. ISBN13 is valid
pm.test("ISBN13 result is true", function () {
    pm.expect(responseBody).to.include("true");
});

// 8. Content-Type header exists
pm.test("Content-Type header exists", function () {
    pm.expect(pm.response.headers.has("Content-Type")).to.be.true;
});

// 9. Content-Type is XML
pm.test("Content-Type is XML", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("text/xml");
});

// 10. Server header exists
pm.test("Server header exists", function () {
    pm.expect(pm.response.headers.has("Server")).to.be.true;
});

